def T(en,ur=None,ps=None):return f'{en} || {ur or en} || {ps or en}'
def P(en,ur,ps):return f'p {T(en,ur,ps)}\n'
def EX(n,en,ur,ps):return f'example {n} | {T(en,ur,ps)}\n'
SOL=P('**Solution:**','**حل:**','**حل:**')
def S(w,h,aria,body):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{aria}"><title>{aria}</title>{body}</svg>'
tx=lambda x,y,t,sz=13,fill='#0f172a':f'<text x="{x}" y="{y}" font-size="{sz}" fill="{fill}" font-family="sans-serif">{t}</text>'
def gfig(fn,xr,yr,aria,pts,w=230,h=190,odd=False):
    n=80
    xmin,xmax=xr;ymin,ymax=yr
    X=lambda x:15+(x-xmin)/(xmax-xmin)*(w-30)
    Y=lambda y:h-15-(y-ymin)/(ymax-ymin)*(h-30)
    d=' '.join(f'{"M" if i==0 else "L"}{X(xmin+(xmax-xmin)*i/n):.1f} {Y(fn(xmin+(xmax-xmin)*i/n)):.1f}' for i in range(n+1))
    s=f'<path d="M10 {Y(0):.1f}H{w-8}M{X(0):.1f} {h-8}V8" stroke="#334155" stroke-width="1.4" fill="none"/><path d="{d}" fill="none" stroke="#dc2626" stroke-width="2.2"/>'
    for px,py,lab,dx,dy in pts:
        s+=f'<circle cx="{X(px):.1f}" cy="{Y(py):.1f}" r="3" fill="#2563eb"/>'+tx(X(px)+dx,Y(py)+dy,lab,11)
    s+=f'<path d="M{X(pts[0][0]):.1f} {Y(pts[0][1]):.1f}H{X(pts[1][0]):.1f}" stroke="#64748b" stroke-dasharray="3 3"/>'
    return S(w,h,aria,s)
